const CSS = `
:root{color-scheme:dark;font-family:Arial,"Noto Sans Hebrew",sans-serif;background:#071426;color:#f8fafc}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 15% 85%,#351b53 0,transparent 30%),radial-gradient(circle at 80% 10%,#102c50 0,transparent 35%),#071426;color:#f8fafc}a{color:inherit}.shell{width:min(1080px,calc(100% - 32px));margin:auto;padding:34px 0 54px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:48px}.brand{display:flex;align-items:center;gap:10px;font-weight:800;text-decoration:none}.mark{border:1px solid #5eead4;border-radius:12px;padding:7px 9px;color:#5eead4}.nav{display:flex;gap:16px;flex-wrap:wrap;color:#cbd5e1}.nav a{text-decoration:none}.hero{text-align:center;max-width:820px;margin:auto}.eyebrow{color:#94a3b8;margin:10px 0}.hero h1{font-size:clamp(2rem,7vw,4.2rem);margin:0}.lead{color:#bdc8d8;line-height:1.85;font-size:1.08rem}.projects{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin:46px 0}.card{position:relative;display:block;min-height:300px;padding:32px;border:1px solid #334155;border-radius:30px;background:linear-gradient(145deg,rgba(12,32,57,.95),rgba(7,20,38,.96));color:inherit;text-decoration:none;box-shadow:0 20px 60px #0004}.card.purple{background:linear-gradient(145deg,#35274c,#08192b 70%)}.card.warm{background:linear-gradient(145deg,#3b3430,#08192b 70%)}.icon{display:inline-grid;place-items:center;width:70px;height:70px;border-radius:20px;background:#ffffff12;overflow:hidden}.project-logo{display:block;width:100%;height:100%;object-fit:cover}.wallet-logo{background:#fff;object-fit:contain;padding:5px}.arrow{position:absolute;left:32px;top:40px;font-size:1.6rem}.card h2{font-size:2rem;margin:58px 0 14px}.card p,.muted{color:#bdc8d8;line-height:1.75}.domain{display:block;color:#dbe5f2;margin-top:22px;direction:ltr;text-align:right}.content{border:1px solid #25364d;border-radius:30px;padding:34px;background:#07172acc;margin:26px 0}.content h2{font-size:1.65rem;margin-top:0}.content h3{margin-top:30px}.content p,.content li{color:#c7d2e0;line-height:1.9}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.step{padding:22px;border-radius:20px;background:#ffffff08;border:1px solid #25364d}.step b{display:block;margin-bottom:8px;color:#fff}.cta{display:inline-block;margin-top:12px;padding:13px 20px;border-radius:14px;background:#0c79d8;text-decoration:none;font-weight:700}.footer-links{display:flex;justify-content:center;gap:18px;flex-wrap:wrap;margin-bottom:16px}footer{text-align:center;color:#8492a6;padding:20px 16px 40px}.legal{max-width:850px;margin:auto}.legal h1{font-size:2.5rem}.legal h2{margin-top:32px}.legal p,.legal li{color:#c7d2e0;line-height:1.9}@media(max-width:760px){.top{align-items:flex-start;flex-direction:column}.projects,.steps{grid-template-columns:1fr}.card{min-height:270px}.card h2{margin-top:42px}}
`;

const ION = `<svg class="project-logo" viewBox="0 0 512 512" aria-hidden="true"><defs><linearGradient id="ionbg" x1="56" y1="32" x2="456" y2="480" gradientUnits="userSpaceOnUse"><stop stop-color="#0EA5E9"/><stop offset=".48" stop-color="#2563EB"/><stop offset="1" stop-color="#071B35"/></linearGradient></defs><rect x="24" y="24" width="464" height="464" rx="122" fill="url(#ionbg)"/><circle cx="256" cy="256" r="118" fill="#061A32" fill-opacity=".5" stroke="#E0F2FE" stroke-width="15"/><ellipse cx="256" cy="256" rx="178" ry="74" transform="rotate(-22 256 256)" fill="none" stroke="#7DD3FC" stroke-width="14"/><path d="M256 112v288M112 256h288" stroke="#E0F2FE" stroke-width="13" stroke-linecap="round"/><circle cx="256" cy="256" r="24" fill="#F8FAFC"/><circle cx="409" cy="196" r="18" fill="#34D399" stroke="#ECFDF5" stroke-width="8"/></svg>`;
