function layout(title, description, body, canonical="/"){
  return `<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#071426"><title>${title}</title><meta name="description" content="${description}"><link rel="canonical" href="https://hania360.com${canonical}"><style>${CSS}</style><script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-5716914780099032" crossorigin="anonymous"></script></head><body><main class="shell"><div class="top"><a class="brand" href="/"><span class="mark">H360</span><span>Hania360</span></a><nav class="nav" aria-label="ניווט ראשי"><a href="/">בית</a><a href="/guides">מדריכים</a><a href="/about">אודות</a><a href="/privacy">פרטיות</a><a href="/terms">תנאי שימוש</a><a href="/contact">יצירת קשר</a></nav></div>${body}</main><footer><div class="footer-links"><a href="/guides">מדריכים</a><a href="/about">אודות</a><a href="/privacy">מדיניות פרטיות</a><a href="/terms">תנאי שימוש</a><a href="/contact">יצירת קשר</a></div>© 2026 Hania360 · נבנה בישראל</footer></body></html>`;
}

const HOME = layout("Hania360 — טכנולוגיה, יצירה ורעיונות במקום אחד","Hania360 הוא הבית הדיגיטלי של הנחה בכיס, HaniaION ואלינויה — כלים ושירותים שימושיים במקום אחד.",`
<header class="hero"><p class="eyebrow">טכנולוגיה · יצירה · רעיונות</p><h1>כלים ומדריכים לחיסכון, לניווט מדויק וליצירה</h1><p class="lead">Hania360 הוא הבית של שלושה פרויקטים עצמאיים ושל מדריכים מעשיים שנכתבו מתוך העבודה עליהם: איך לחסוך לפני קנייה, להבין טוב יותר GPS ויונוספירה, ולהתחיל ליצור בעבודת יד.</p><a class="cta" href="/guides">לכל המדריכים</a></header>
<section class="projects" aria-label="הפרויקטים של Hania360">
<a class="card" href="https://gps.hania360.com/"><span class="icon">${ION}</span><span class="arrow">←</span><h2>HaniaION</h2><p>מערכת לחישובי GPS ונתוני יונוספירה, בדיקות והתראות. מיועדת לגישה נוחה לנתונים ולכלים ממחשב או מטלפון.</p><span class="domain">gps.hania360.com</span></a>
<a class="card purple" href="https://elinoya.hania360.com/"><span class="icon">${ELI}</span><span class="arrow">←</span><h2>אלינויה</h2><p>סדנאות בוטיק ליצירה והשראה, ובהן עבודה עם בטון פולימרי ונרות מעוצבים. באתר ניתן להכיר את הסדנאות ולבדוק מועדים.</p><span class="domain">elinoya.hania360.com</span></a>
<a class="card warm" href="https://save.hania360.com/"><span class="icon"><img class="project-logo wallet-logo" src="https://save.hania360.com/icons/icon-192.png" alt=""></span><span class="arrow">←</span><h2>הנחה בכיס</h2><p>כלי שמרכז הטבות, כרטיסים, שוברים וקאשבק כדי לעזור לבדוק מה משתלם לפני התשלום ולרכז את אפשרויות החיסכון במקום אחד.</p><span class="domain">save.hania360.com</span></a>
</section>
<section class="content"><h2>מדריכים נבחרים</h2><p><a href="/guides/compare-benefits-before-buying"><strong>איך לבדוק איזו הטבה הכי משתלמת לפני שמשלמים</strong></a><br><span class="muted">השוואה בין מועדונים, כרטיסי אשראי, שוברים וקאשבק לפני קנייה.</span></p><p><a href="/guides/ionosphere-and-gps-accuracy"><strong>היונוספירה ו־GPS: למה המיקום שלכם זז בלי שזזתם</strong></a><br><span class="muted">איך האטמוספרה משפיעה על אותות הלוויין ועל דיוק המיקום.</span></p><p><a href="/guides/beginners-guide-candle-making"><strong>יציקת נרות מעוצבים: מדריך למתחילים</strong></a><br><span class="muted">שעווה, פתיל, ריח, טמפרטורה והבעיות הנפוצות ביציקה.</span></p><p><a class="cta" href="/guides">לכל 14 המדריכים</a></p></section>
<section class="content"><h2>הנחה בכיס — למצוא את החיסכון לפני שמשלמים</h2><p>כשלאותה חנות יש הטבות בכמה מועדונים, כרטיסי אשראי, שוברים או שירותי קאשבק, קל לפספס את האפשרות המשתלמת. הנחה בכיס נועד לצמצם את החיפוש הזה: בוחרים חנות וסכום קנייה, בודקים את האפשרויות הרלוונטיות ומקבלים דרך ברורה להמשיך.</p><div class="steps"><div class="step"><b>1. מחפשים חנות</b><span class="muted">מאתרים את בית העסק במאגר ומזינים את סכום הקנייה.</span></div><div class="step"><b>2. משווים אפשרויות</b><span class="muted">המערכת מרכזת הטבות רלוונטיות ומציגה אפשרות מובילה וחלופות כשישנן.</span></div><div class="step"><b>3. משלמים ומעדכנים</b><span class="muted">ממשיכים לאמצעי המתאים וניתן לעדכן את החיסכון לאחר התשלום.</span></div></div><p>המערכת כוללת גם ארנק לשוברים דיגיטליים, כדי שלא יהיה צורך לשמור קודים והודעות במקומות שונים. מידע על הטבות עשוי להשתנות, ולכן לפני רכישה חשוב לבדוק גם את התנאים העדכניים של הגוף שמעניק את ההטבה.</p><a class="cta" href="https://save.hania360.com/">כניסה להנחה בכיס</a></section>
<section class="content"><h2>מה הערך של Hania360?</h2><p>המטרה של Hania360 היא לא להיות עמוד קישורים בלבד. זהו בית לפרויקטים עצמאיים עם שימוש מעשי: HaniaION מרכז כלים טכנולוגיים בתחום GPS והיונוספירה; אלינויה מחברת בין מידע, הרשמה וחוויית יצירה; והנחה בכיס מרכז מידע וכלים לקבלת החלטה לפני תשלום. אנחנו ממשיכים לשפר את המוצרים, את נגישות המידע ואת חוויית השימוש בהתאם לצרכים שעולים מהשטח.</p><h3>שקיפות</h3><p>בחלק מהשירותים עשויים להופיע קישורי שותפים או פרסום. כאשר קישור עשוי להניב עמלה, המטרה היא לשמור על גילוי נאות ולאפשר למשתמש להבין זאת. קבלת עמלה אינה משנה את המחיר למשתמש ואינה מחליפה בדיקה עצמאית של תנאי ההטבה.</p></section>
`,"/");

function guidesPage(){
  const cats=["חיסכון","GPS ויונוספירה","יצירה"];
  const sections=cats.map(cat=>`<h2>${cat}</h2>`+ARTICLES.filter(a=>a.cat===cat).map(a=>`<p><a href="/guides/${a.slug}">${a.title}</a><br><span class="muted">${a.desc} · ${a.read} דקות קריאה</span></p>`).join("")).join("");
  return layout("מדריכים — Hania360","מדריכים מעשיים מתוך הפרויקטים של Hania360 בתחומי חיסכון, GPS ויצירה.",`<article class="legal"><h1>מדריכים</h1><p>אזור המדריכים של Hania360 נבנה מתוך העבודה על שלושת הפרויקטים שלנו. כאן מרוכזים המדריכים המלאים בתחומי חיסכון, GPS ויונוספירה ויצירה.</p>${sections}</article>`,"/guides");
}

const ARTICLES = [{"slug":"compare-benefits-before-buying","cat":"חיסכון","title":"איך לבדוק איזו הטבה הכי משתלמת לפני שמשלמים","desc":"מדריך מעשי להשוואה בין מועדוני צרכנות, כרטיסי אשראי, שוברים וקאשבק לפני קנייה — כולל דוגמת חישוב ושלוש טעויות נפוצות.","read":7,"body":"\n<p>כמעט לכל חנות גדולה בישראל יש היום כמה דרכים לקבל הנחה: מועדון לקוחות של הרשת, הטבה דרך מועדון של כרטיס אשראי, שובר שנקנה מראש בהנחה, או החזר כספי דרך אתר קאשבק. הבעיה היא שהמידע מפוזר, ובקופה אין זמן לבדוק. המדריך הזה מסביר איך לעשות את ההשוואה בכמה דקות, ולמה ההנחה הגדולה ביותר על הנייר היא לא תמיד המשתלמת ביותר בפועל.</p>\n\n<h2>שלב 1: להבין מה בדיוק משווים</h2>\n<p>לפני שמשווים אחוזים, צריך לדעת איזה סוג הטבה עומד מולכם. יש ארבעה סוגים עיקריים, ולכל אחד היגיון אחר:</p>\n<ul>\n<li><strong>הנחה מיידית בקופה</strong> — המחיר יורד כבר ברגע התשלום. זה הסוג הפשוט והבטוח ביותר.</li>\n<li><strong>שובר או תו קנייה בהנחה</strong> — קונים מראש, למשל שובר של 200 ₪ ב־170 ₪. החיסכון אמיתי, אבל הכסף \"ננעל\" אצל בית העסק עד שמשתמשים בו.</li>\n<li><strong>קאשבק</strong> — משלמים מחיר מלא ומקבלים חלק מהסכום בחזרה מאוחר יותר. יש כאן סיכון: לפעמים העסקה לא נרשמת, ולפעמים יש סכום מינימלי למשיכה.</li>\n<li><strong>נקודות או הטבה עתידית</strong> — צבירה שתהיה שווה משהו רק בקנייה הבאה. כדאי לתת לה משקל נמוך יותר, כי לא בטוח שתנצלו אותה.</li>\n</ul>\n\n<h2>שלב 2: לחשב סכום נטו ולא אחוזים</h2>\n<p>אחוזים מטעים כשיש תנאים. \"20% הנחה בקנייה מעל 400 ₪\" לא שווה כלום אם הסל שלכם הוא 350 ₪. לכן הדרך הנכונה היא לתרגם כל אפשרות לשאלה אחת: כמה כסף ייצא לי מהכיס בסוף?</p>\n<p>נניח קנייה של 500 ₪ בחנות ביגוד, עם שלוש אפשרויות:</p>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>אפשרות</th><th>תנאי</th><th>עלות נטו</th></tr></thead>\n<tbody>\n<tr><td>הנחת מועדון כרטיס אשראי 10%</td><td>ללא מינימום</td><td>450 ₪</td></tr>\n<tr><td>שובר 200 ₪ שנקנה ב־170 ₪ (x2) + יתרה במזומן</td><td>השובר תקף רק ברשת</td><td>440 ₪</td></tr>\n<tr><td>קאשבק 12%</td><td>ההחזר מתקבל אחרי 60 יום</td><td>440 ₪ (אם נרשם)</td></tr>\n</tbody></table></div>\n<p>על הנייר השובר והקאשבק שווים. אבל בשובר החיסכון ודאי, ובקאשבק הוא תלוי ברישום העסקה ובזמן ההמתנה. במקרה כזה השובר עדיף. ואם אפשר לשלם את היתרה בכרטיס שנותן את ה־10%? לפעמים ההטבות מצטברות, ואז המשתלם ביותר הוא שילוב.</p>\n\n<h2>שלב 3: לבדוק אם אפשר לשלב</h2>\n<p>הכסף הגדול נמצא בשילובים. דוגמה נפוצה: להיכנס לאתר החנות דרך אתר קאשבק, ולשלם בכרטיס אשראי שיש לו הטבה באותה רשת. שתי ההטבות ניתנות על ידי גופים שונים, ולכן לרוב הן לא סותרות. מה שכמעט תמיד <em>לא</em> מצטבר הוא שתי הנחות של אותה חנות (למשל קופון של האתר יחד עם מבצע אחר של האתר).</p>\n<p>לפני שמשלבים, כדאי לקרוא את התנאים של אתר הקאשבק: חלק מהם לא מחזירים כסף כשמשתמשים בקופון שלא הופיע אצלם.</p>\n\n<h2>שלוש טעויות שעולות כסף</h2>\n<ol>\n<li><strong>לקנות שובר ולשכוח אותו.</strong> שובר שלא נוצל הוא הפסד מלא. אם אתם לא בטוחים שתקנו ברשת בחודשים הקרובים, ההנחה על השובר לא שווה את הסיכון.</li>\n<li><strong>להגדיל את הסל כדי לעבור רף.</strong> אם הוספתם פריט של 80 ₪ כדי לקבל הנחה של 50 ₪, לא חסכתם — הוצאתם 30 ₪ נוספים.</li>\n<li><strong>לבדוק הטבה ישנה.</strong> הטבות של מועדונים משתנות לעתים קרובות. מידע מלפני חודשיים עלול להיות לא רלוונטי. תמיד כדאי לאמת באתר של הגוף שנותן את ההטבה.</li>\n</ol>\n\n<h2>איך לעשות את זה מהר</h2>\n<p>הכלל הפשוט: לפני כל קנייה מעל כמה מאות שקלים, להקדיש שתי דקות לשאלה \"אילו הטבות יש לי ברשת הזו?\". בדיוק בשביל זה בנינו את <a href=\"https://save.hania360.com/\">הנחה בכיס</a>: בוחרים חנות וסכום, ומקבלים את האפשרויות הרלוונטיות מרוכזות. גם בלי הכלי, רשימה קצרה של המועדונים והכרטיסים שיש לכם, שמורה בטלפון, חוסכת הרבה חיפושים.</p>\n"},{"slug":"how-cashback-works","cat":"חיסכון","title":"קאשבק: איך זה עובד באמת ומה לבדוק לפני שסומכים עליו","desc":"מאיפה מגיע הכסף של הקאשבק, למה עסקאות לפעמים לא נרשמות, ומה לעשות כדי שההחזר באמת יגיע.","read":6,"body":"\n<p>אתרי קאשבק מבטיחים משהו שנשמע טוב מכדי להיות אמיתי: קונים כרגיל, ומקבלים חלק מהכסף בחזרה. בפועל זה עובד, אבל רק כשמבינים את המנגנון. מי שלא מבין אותו מגלה אחרי חודשיים שההחזר \"לא נרשם\".</p>\n\n<h2>מאיפה מגיע הכסף</h2>\n<p>חנויות אונליין משלמות עמלה לאתרים שמפנים אליהן לקוחות — זה נקרא שיווק שותפים. אתר הקאשבק מקבל את העמלה הזו ומעביר חלק ממנה אליכם. כלומר, הקאשבק הוא לא מתנה מהחנות, אלא חלוקה של דמי התיווך. מכאן נובעים כמעט כל הכללים:</p>\n<ul>\n<li>ההחזר ניתן רק אם החנות מזהה שהגעתם דרך הקישור של אתר הקאשבק.</li>\n<li>ההחזר מאושר רק אחרי שהחנות מאשרת לאתר את העמלה — בדרך כלל אחרי שעבר מועד ההחזרות.</li>\n<li>אם ביטלתם או החזרתם מוצר, גם העמלה מתבטלת, וכך גם הקאשבק.</li>\n</ul>\n\n<h2>למה עסקאות לא נרשמות</h2>\n<p>הזיהוי נעשה בדרך כלל באמצעות עוגייה (cookie) שנשמרת בדפדפן כשלוחצים על הקישור. הדברים שהכי הרבה פעמים שוברים את הזיהוי:</p>\n<ol>\n<li><strong>חוסם פרסומות או מצב גלישה פרטית</strong> שמונעים שמירת עוגיות.</li>\n<li><strong>מעבר בין מכשירים</strong> — לחצתם על הקישור בטלפון והשלמתם את הקנייה במחשב.</li>\n<li><strong>לחיצה על קישור אחר בדרך</strong> — למשל קופון מאתר אחר, שדורס את השיוך.</li>\n<li><strong>זמן רב מדי</strong> בין הלחיצה לרכישה. לכל חנות יש חלון זמן משלה.</li>\n<li><strong>שימוש בקופון שלא אושר</strong> על ידי אתר הקאשבק.</li>\n</ol>\n\n<h2>הרגלים שמגדילים את הסיכוי לקבל את הכסף</h2>\n<p>הכלל החשוב ביותר: להשלים את הקנייה באותו דפדפן ובאותה ישיבה שבה לחצתם על קישור הקאשבק, בלי לקפוץ לאתרים אחרים באמצע. כדאי גם לצלם מסך של אישור ההזמנה ולשמור את מספר ההזמנה — אם העסקה לא מופיעה אחרי כמה ימים, רוב אתרי הקאשבק מאפשרים לפתוח פנייה, והם יבקשו בדיוק את הפרטים האלה.</p>\n\n<h2>האם קאשבק עדיף על הנחה מיידית?</h2>\n<p>לא תמיד. הנחה בקופה היא כסף ודאי, עכשיו. קאשבק הוא כסף עתידי ולא בטוח. כשהפער קטן — למשל 8% הנחה מיידית מול 10% קאשבק — ההנחה המיידית בדרך כלל עדיפה. כשהפער גדול, או כשאפשר לקבל את שתיהן יחד, הקאשבק מצדיק את עצמו. כדאי גם לבדוק את סף המשיכה: אם צריך לצבור 100 ₪ לפני שאפשר למשוך, וקונים דרך האתר רק פעמיים בשנה, הכסף עלול להיתקע שם הרבה זמן.</p>\n\n<h2>שקיפות</h2>\n<p>גם ב־Hania360 חלק מהקישורים עשויים להיות קישורי שותפים. זה לא משנה את המחיר שאתם משלמים, ובכל מקרה כדאי לבדוק את התנאים העדכניים ישירות אצל מי שמעניק את ההטבה.</p>\n"},{"slug":"digital-vouchers-guide","cat":"חיסכון","title":"שוברים דיגיטליים: איך לא לאבד את הכסף שכבר שילמתם","desc":"איך לנהל שוברים וקודים דיגיטליים, מה לבדוק לפני שקונים שובר בהנחה, ומה הזכויות שלכם כצרכנים.","read":6,"body":"\n<p>שובר דיגיטלי הוא בעצם כסף ששילמתם מראש. ובכל זאת, הרבה אנשים מחזיקים שוברים בשווי מאות שקלים שפזורים בין הודעות SMS, מיילים וצילומי מסך — ושוכחים מהם. המדריך הזה עוסק בשני דברים: איך להחליט אם לקנות שובר, ואיך לוודא שתשתמשו בו.</p>\n\n<h2>לפני שקונים שובר בהנחה</h2>\n<p>שובר בהנחה נראה כמו חיסכון ודאי, וזה נכון רק אם ארבעה תנאים מתקיימים:</p>\n<ul>\n<li><strong>אתם כבר מתכננים לקנות ברשת הזו.</strong> שובר שגורם לכם לקנות משהו שלא הייתם קונים הוא לא חיסכון.</li>\n<li><strong>השובר תקף בסניפים ובערוצים שבהם אתם קונים.</strong> יש שוברים שלא תקפים באתר האינטרנט, בזכיינים או במבצעים.</li>\n<li><strong>אפשר לממש אותו בחלקים</strong> — או שהסכום מתאים לקנייה אחת. שובר שחייבים לממש במלואו בבת אחת עלול להשאיר יתרה שתאבד.</li>\n<li><strong>תאריך התוקף סביר</strong> ביחס לתוכניות שלכם.</li>\n</ul>\n\n<h2>הזכויות שלכם</h2>\n<p>בישראל חוק הגנת הצרכן מסדיר את נושא תווי הקנייה והשוברים, כולל תוקף מינימלי והחובה לציין את התנאים בצורה ברורה. הפרטים המדויקים משתנים לפי סוג השובר ומי הנפיק אותו, ולכן כדאי לבדוק באתר הרשות להגנת הצרכן ולסחר הוגן אם נתקלתם בסירוב לכבד שובר. בכל מקרה, שמרו את הקבלה על רכישת השובר — היא ההוכחה שלכם.</p>\n\n<h2>שיטה פשוטה לניהול שוברים</h2>\n<ol>\n<li><strong>מקום אחד.</strong> ברגע שמתקבל שובר, מעבירים אותו למקום אחד קבוע — אפליקציה, תיקייה בטלפון או ארנק שוברים. לא משאירים אותו בתיבת המייל.</li>\n<li><strong>שלושה פרטים לכל שובר:</strong> שם הרשת, היתרה ותאריך התוקף. בלי אלה אי אפשר לדעת מה יש לכם.</li>\n<li><strong>תזכורת חודש לפני תפוגה.</strong> זה מספיק זמן לתכנן קנייה.</li>\n<li><strong>עדכון יתרה אחרי כל שימוש.</strong> אחרת תגיעו לקופה עם שובר שכבר נוצל.</li>\n<li><strong>לא לשתף קודים</strong> בצילומי מסך ציבוריים או בקבוצות — מי שיש לו את הקוד יכול להשתמש בו.</li>\n</ol>\n\n<h2>מה עושים עם שובר שלא תצטרכו</h2>\n<p>אם ברור שלא תשתמשו בשובר, עדיף לפעול מוקדם: לתת אותו כמתנה למישהו שקונה ברשת, או לבדוק אם הנפיק מאפשר העברה. לפני שמוכרים שובר לאדם זר, כדאי לבדוק בתנאים שמותר להעביר אותו, ולהיזהר מהונאות — העבירו את הקוד רק אחרי שהתשלום התקבל בפועל.</p>\n\n<p>ב<a href=\"https://save.hania360.com/\">הנחה בכיס</a> יש ארנק שוברים שנבנה בדיוק לצורך הזה: שמירת הקודים, היתרה והתוקף במקום אחד.</p>\n"},{"slug":"ionosphere-and-gps-accuracy","cat":"GPS ויונוספירה","title":"היונוספירה ו־GPS: למה המיקום שלכם זז בלי שזזתם","desc":"הסבר נגיש על השכבה הטעונה של האטמוספרה, איך היא מעכבת את אותות הלוויין, מה זה TEC ואיך מקלטים מתקנים את השגיאה.","read":8,"body":"\n<p>כל מי שעבד עם מקלט GPS מדויק מכיר את זה: המכשיר עומד במקום, והמיקום נודד בכמה סנטימטרים ולפעמים בכמה מטרים. חלק גדול מהנדידה הזו לא נוצר במקלט ולא בלוויין, אלא בדרך ביניהם — בשכבה של האטמוספרה שנקראת יונוספירה.</p>\n\n<h2>מה זו היונוספירה</h2>\n<p>היונוספירה היא אזור באטמוספרה העליונה, בערך בגובה 60 עד 1,000 ק\"מ, שבו קרינת השמש מפרקת אטומים ומולקולות ליונים ולאלקטרונים חופשיים. הריכוז של האלקטרונים האלה לא קבוע: הוא עולה ביום ויורד בלילה, משתנה עם העונות, תלוי במחזור הפעילות של השמש (כ־11 שנים), ומגיב בחדות לסערות גאומגנטיות.</p>\n\n<h2>למה היא משפיעה על GPS</h2>\n<p>אות GPS הוא גל רדיו. כשהוא עובר דרך שכבה עם אלקטרונים חופשיים, הוא מתעכב. המקלט מחשב את המרחק ללוויין לפי זמן ההגעה של האות, ולכן כל עיכוב מתורגם למרחק שגוי. העיכוב הזה הוא אחד ממקורות השגיאה הגדולים ביותר במערכות ניווט לוויינית, ובתנאים קיצוניים הוא יכול להגיע לעשרות מטרים.</p>\n\n<h2>TEC — המספר שמתאר את כל זה</h2>\n<p>הגודל שמשמש למדידת ההשפעה נקרא <strong>TEC</strong> (Total Electron Content): כמות האלקטרונים הכוללת לאורך המסלול של האות. היחידה המקובלת היא TECU, שווה ל־10<sup>16</sup> אלקטרונים במטר מרובע. לכלל אצבע: בתדר L1 של GPS, כל TECU מוסיף בערך 16 ס\"מ לשגיאת המרחק. ביום רגוע באזור שלנו ערכי TEC יכולים להיות עשרות יחידות, ובזמן סערה — הרבה יותר.</p>\n<p>שני דברים חשובים לזכור:</p>\n<ul>\n<li>העיכוב תלוי בזווית: אות מלוויין נמוך באופק עובר מסלול ארוך יותר ביונוספירה, ולכן מושפע יותר.</li>\n<li>העיכוב תלוי בתדר: ככל שהתדר נמוך יותר, העיכוב גדול יותר. זו בדיוק התכונה שמאפשרת לתקן אותו.</li>\n</ul>\n\n<h2>איך מקלטים מתקנים את השגיאה</h2>\n<p><strong>מקלט בתדר יחיד</strong> (רוב הטלפונים הישנים) משתמש במודל חיזוי שהלוויינים משדרים. המודל הזה מתקן חלק מהשגיאה — בערך מחצית בממוצע — אבל לא מתמודד טוב עם שינויים מקומיים ומהירים.</p>\n<p><strong>מקלט דו־תדרי</strong> (L1 ו־L5, או L1 ו־L2) מודד את אותו אות בשני תדרים. מאחר שהעיכוב תלוי בתדר, ההפרש בין שתי המדידות מאפשר לחשב את ה־TEC ולבטל כמעט את כל השגיאה היונוספרית. זו אחת הסיבות שמכשירים חדשים יותר מדויקים יותר גם בלי שום שינוי בלוויינים.</p>\n<p><strong>RTK ותיקונים דיפרנציאליים</strong> משתמשים בתחנת בסיס במיקום ידוע. מאחר שהבסיס והמקלט \"רואים\" יונוספירה דומה, אפשר להעביר תיקון ולבטל את רוב ההשפעה. אבל זה עובד טוב רק כשהמרחק בין הבסיס למקלט קצר יחסית, וכשהיונוספירה לא משתנה בחדות בין שתי הנקודות.</p>\n\n<h2>מתי כדאי לשים לב</h2>\n<p>הזמנים הבעייתיים הם שעות אחר הצהריים, כשה־TEC בשיאו; השעות שאחרי השקיעה, שבהן עלולים להופיע שינויים מהירים (נצנוץ, scintillation); ותקופות של סערה גאומגנטית. מי שעושה מדידות מדויקות — מודדים, חקלאות מדייקת, רחפנים — ירוויח ממעקב אחרי מצב היונוספירה לפני יציאה לשטח.</p>\n<p>בשביל זה נבנתה <a href=\"https://gps.hania360.com/\">HaniaION</a>: גישה לנתוני יונוספירה וחישובי GPS, עם בדיקות והתראות, ממחשב או מטלפון.</p>\n"},{"slug":"kp-index-geomagnetic-storms","cat":"GPS ויונוספירה","title":"מדד Kp וסערות גאומגנטיות: מה זה אומר למי שעובד עם GPS","desc":"איך קוראים את מדד Kp ואת סולם הסערות G1–G5, איך סערה משפיעה על RTK ועל ניווט, ומה כדאי לעשות לפני יציאה לשטח.","read":7,"body":"\n<p>כשמתפרסמת ידיעה על \"סערה סולארית\", רוב האנשים חושבים על זוהר צפוני. למי שעובד עם ניווט לווייני מדויק, זו בעיקר שאלה מעשית: האם היום אפשר לסמוך על המדידות?</p>\n\n<h2>מה קורה בזמן סערה גאומגנטית</h2>\n<p>השמש פולטת כל הזמן זרם של חלקיקים טעונים (רוח סולארית), ומדי פעם גם התפרצויות גדולות של חומר. כשהחומר הזה פוגע בשדה המגנטי של כדור הארץ, השדה מתעוות — זו סערה גאומגנטית. אחת התוצאות היא שינוי חד בכמות ובפיזור של האלקטרונים ביונוספירה, ולכן גם בעיכוב של אותות GPS.</p>\n\n<h2>איך קוראים את מדד Kp</h2>\n<p>מדד Kp מסכם את עוצמת ההפרעה בשדה המגנטי לאורך פרקי זמן של שלוש שעות, בסולם מ־0 עד 9:</p>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Kp</th><th>מצב</th><th>סולם NOAA</th></tr></thead>\n<tbody>\n<tr><td>0–3</td><td>שקט עד לא יציב</td><td>—</td></tr>\n<tr><td>4</td><td>פעיל</td><td>—</td></tr>\n<tr><td>5</td><td>סערה חלשה</td><td>G1</td></tr>\n<tr><td>6</td><td>סערה בינונית</td><td>G2</td></tr>\n<tr><td>7</td><td>סערה חזקה</td><td>G3</td></tr>\n<tr><td>8</td><td>סערה חמורה</td><td>G4</td></tr>\n<tr><td>9</td><td>סערה קיצונית</td><td>G5</td></tr>\n</tbody></table></div>\n<p>חשוב להבין שמדד Kp הוא מדד גלובלי של השדה המגנטי, ולא מדידה ישירה של היונוספירה מעל המקום שלכם. יש ימים עם Kp גבוה שבהם ההשפעה המקומית קטנה, ולהפך. לכן כדאי להסתכל גם על נתוני TEC מקומיים ולא רק על Kp.</p>\n\n<h2>ההשפעה על עבודה בשטח</h2>\n<ul>\n<li><strong>RTK:</strong> זמן ארוך יותר עד להשגת פתרון Fix, איבוד Fix תכוף, ולפעמים פתרון שנראה תקין אבל מוסט. ככל שהמרחק מתחנת הבסיס גדול יותר, הבעיה חמורה יותר.</li>\n<li><strong>מקלטים בתדר יחיד:</strong> שגיאת מיקום גדולה יותר, כי מודל התיקון המשודר לא מתאים לתנאים חריגים.</li>\n<li><strong>רחפנים:</strong> מערכות שנשענות על RTK לצילום ממופה או לנחיתה מדויקת עלולות לאבד דיוק באמצע משימה.</li>\n<li><strong>נצנוץ (scintillation):</strong> תנודות מהירות בעוצמת האות שיכולות לגרום לאיבוד נעילה על לוויינים. התופעה שכיחה יותר באזורים קרובים לקו המשווה ובקווי רוחב גבוהים, אבל סערות חזקות מרחיבות אותה.</li>\n</ul>\n\n<h2>רשימת בדיקה לפני יציאה לשטח</h2>\n<ol>\n<li>לבדוק את תחזית Kp ל־24 השעות הקרובות.</li>\n<li>לבדוק את ערכי ה־TEC והשינויים בהם באזור העבודה.</li>\n<li>אם צפויה סערה — לתכנן את המדידות הקריטיות לשעות הבוקר, ולהימנע מהשעות שאחרי השקיעה.</li>\n<li>לקצר את המרחק לתחנת הבסיס, או לעבוד עם רשת תיקונים צפופה יותר.</li>\n<li>להאריך את זמן המדידה בכל נקודה, ולמדוד נקודת ביקורת ידועה בתחילת העבודה ובסופה.</li>\n</ol>\n<p>ב<a href=\"https://gps.hania360.com/\">HaniaION</a> אפשר לעקוב אחרי נתוני יונוספירה ולהגדיר התראות, כדי לדעת מראש אם היום מתאים למדידות מדויקות.</p>\n"},{"slug":"beginners-guide-candle-making","cat":"יצירה","title":"יציקת נרות מעוצבים: מדריך למתחילים","desc":"איך בוחרים שעווה ופתיל, באיזו טמפרטורה מוסיפים ריח ויוצקים, כמה זמן מחכים — ואיך מתקנים את הבעיות הנפוצות.","read":8,"body":"\n<p>יציקת נרות היא אחת מתחומי היצירה הנגישים ביותר: לא צריך סדנה מאובזרת, והתוצאה שימושית. ובכל זאת, רוב הנרות הראשונים יוצאים עם סדקים, בורות באמצע או פתיל שנחנק. ההבדל בין נר ביתי לנר שנראה מקצועי נמצא בכמה פרטים קטנים.</p>\n\n<h2>בחירת שעווה</h2>\n<ul>\n<li><strong>שעוות סויה</strong> — הבחירה הנפוצה למתחילים בנרות בכלי. נמסה בטמפרטורה נמוכה יחסית, קלה לניקוי, ונשרפת לאט. חסרון: לפעמים יוצרת משטח לא אחיד.</li>\n<li><strong>שעוות פרפין</strong> — מחזיקה ריח חזק, נותנת צבעים חיים וגימור חלק. מתאימה במיוחד לנרות עמודים שמוציאים מתבנית.</li>\n<li><strong>שעוות דבורים</strong> — ריח טבעי וצבע חם, קשה יותר ויקרה יותר. בדרך כלל משלבים אותה עם שעווה אחרת.</li>\n<li><strong>תערובות</strong> — הרבה יצרנים מוכרים תערובות מוכנות שמיועדות לשימוש מסוים (נר בכלי, נר עומד, תבנית). למתחילים זו הדרך הקלה ביותר להצליח.</li>\n</ul>\n<p>הכלל החשוב: לכל שעווה יש הוראות של היצרן לטמפרטורת הוספת ריח ולטמפרטורת יציקה. אלה הנתונים שצריך לעבוד לפיהם, ולא מספרים כלליים מהאינטרנט.</p>\n\n<h2>בחירת פתיל</h2>\n<p>הפתיל הוא הסיבה הראשונה לנרות כושלים. פתיל דק מדי יוצר \"מנהרה\" — בור באמצע והרבה שעווה שלא נשרפת בצדדים. פתיל עבה מדי יוצר להבה גבוהה, עשן וכלי שמתחמם יותר מדי. גודל הפתיל נקבע לפי קוטר הכלי וסוג השעווה, ורוב יצרני הפתילים מפרסמים טבלאות התאמה. אם אתם לא בטוחים, יצקו שני נרות ניסיון עם שני גדלים והשוו.</p>\n\n<h2>התהליך, שלב אחרי שלב</h2>\n<ol>\n<li><strong>הכנה:</strong> ניקוי הכלי, הדבקת בסיס הפתיל למרכז התחתית, וקיבוע הפתיל בעזרת מקל או מחזיק כך שיעמוד ישר.</li>\n<li><strong>המסה:</strong> בסיר כפול (בן מארי), ולא על אש ישירה. מדחום הוא כלי חובה.</li>\n<li><strong>הוספת ריח:</strong> בטמפרטורה שהיצרן ממליץ עליה, ובכמות שהשעווה יכולה לספוג — בדרך כלל 6%–10% ממשקל השעווה. יותר ריח לא תמיד אומר ריח חזק יותר; עודף עלול \"להזיע\" החוצה. ערבבו בעדינות כשתי דקות.</li>\n<li><strong>יציקה:</strong> בטמפרטורת היציקה המומלצת, לאט, כדי לא ליצור בועות.</li>\n<li><strong>קירור:</strong> בחדר בטמפרטורה יציבה, בלי רוח ובלי מקרר. קירור מהיר גורם לסדקים ולמשטח לא אחיד.</li>\n<li><strong>ייצוב (curing):</strong> כאן רוב המתחילים ממהרים. נר סויה צריך בדרך כלל שבוע עד שבועיים לפני שהריח מגיע לשיאו.</li>\n</ol>\n\n<h2>בעיות נפוצות ופתרונות</h2>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>בעיה</th><th>סיבה סבירה</th><th>מה לעשות</th></tr></thead>\n<tbody>\n<tr><td>בור ליד הפתיל</td><td>התכווצות בקירור</td><td>יציקה שנייה קטנה כשהנר כמעט התקרר</td></tr>\n<tr><td>סדקים</td><td>קירור מהיר מדי</td><td>לקרר בחדר חמים יותר, להרחיק ממזגן</td></tr>\n<tr><td>מנהרה בשריפה</td><td>פתיל קטן, או שריפה ראשונה קצרה</td><td>פתיל גדול יותר; בשריפה הראשונה לתת לשכבה העליונה להימס עד הדפנות</td></tr>\n<tr><td>עשן ולהבה גבוהה</td><td>פתיל גדול או ארוך מדי</td><td>לקצר את הפתיל לכחצי סנטימטר לפני כל הדלקה</td></tr>\n<tr><td>ריח חלש</td><td>ייצוב קצר או טמפרטורה לא נכונה</td><td>לחכות עוד שבוע; לבדוק את הוראות היצרן</td></tr>\n</tbody></table></div>\n\n<h2>בטיחות</h2>\n<p>אף פעם לא משאירים שעווה על האש בלי השגחה, ולא מכבים שעווה בוערת במים. נר דולק לא משאירים בלי השגחה, ולא מדליקים ליד וילונות, ילדים או חיות מחמד. כדאי להגביל כל הדלקה לכמה שעות ולכבות את הנר כשנשאר כסנטימטר שעווה בתחתית.</p>\n\n<p>מי שרוצה ללמוד בליווי, עם החומרים והכלים במקום, מוזמן להכיר את הסדנאות של <a href=\"https://elinoya.hania360.com/\">אלינויה</a>.</p>\n"},{"slug":"benefits-you-already-have","cat":"חיסכון","title":"הטבות שכבר יש לכם ואתם כנראה לא מנצלים","desc":"מקום העבודה, קופת החולים, הבנק וכרטיס האשראי מעניקים הטבות שרוב האנשים לא מכירים. כך עושים סדר ומוצאים אותן.","read":6,"body":"<p>לפני שמצטרפים למועדון חדש או מחפשים קופון, כדאי לבדוק משהו פשוט יותר: אילו הטבות כבר מגיעות לכם. רוב האנשים בישראל שייכים לכמה גופים שנותנים הנחות — ובדרך כלל לא יודעים על חלק גדול מהן.</p>\n<h2>המקומות שכדאי לבדוק</h2><ul><li><strong>מקום העבודה.</strong> ארגונים רבים מצטרפים למועדוני הטבות לעובדים, או נותנים שוברים בחגים. לעתים ההטבה מופיעה בפורטל פנימי שאף אחד לא פותח. שאלה אחת למשאבי אנוש יכולה לחשוף הנחות קבועות ברשתות גדולות.</li><li><strong>קופת החולים.</strong> מעבר לשירותי הבריאות, לקופות ולביטוחים המשלימים שלהן יש לעתים הנחות על משקפיים, טיפולים משלימים, חדרי כושר ומוצרים נוספים. התנאים שונים בין קופה לקופה ובין רמות הביטוח.</li><li><strong>הבנק וכרטיסי האשראי.</strong> לכל כרטיס יש מועדון, ולפעמים יש לכם שני כרטיסים עם מועדונים שונים בלי לדעת מה כל אחד נותן.</li><li><strong>ארגונים ואיגודים.</strong> ועד עובדים, איגוד מקצועי, ארגון גמלאים, אגודת סטודנטים — רבים מהם מפעילים מועדון צרכנות.</li><li><strong>מעמד אישי.</strong> סטודנטים, אזרחים ותיקים, חיילים ומשרתי מילואים, בעלי תעודת נכה — לחלק מהקבוצות האלה יש הנחות בתחבורה, בתרבות ובפנאי, שלפעמים מחייבות רק הצגת תעודה.</li></ul>\n<h2>איך עושים סדר בעשר דקות</h2><ol><li>רושמים את כל הגופים שאתם שייכים אליהם: מעסיק, קופת חולים, בנק, כרטיסים, ארגונים.</li><li>לכל גוף בודקים באתר שלו אם יש \"מועדון\" או \"הטבות\".</li><li>מסמנים רק את ההטבות ברשתות שבהן אתם באמת קונים. הנחה ברשת שלא ביקרתם בה שנה לא רלוונטית.</li><li>שומרים את הרשימה במקום זמין בטלפון, ומעדכנים פעם בכמה חודשים — הטבות משתנות.</li></ol>\n<h2>מלכודת: לשלם על הטבות</h2><p>הצד השני של אותו מטבע הוא מועדונים שעולים כסף. דמי כרטיס אשראי, דמי חבר או מנוי חודשי שווים את זה רק אם החיסכון השנתי בפועל גדול מהעלות. חשבון פשוט: כמה חסכתם דרך המועדון בשנה האחרונה? אם התשובה נמוכה מהתשלום — כדאי לשקול לבטל או לבקש פטור. חברות רבות מסכימות לוותר על דמי כרטיס ללקוח שמבקש.</p>\n<p>כשיש לכם הרבה מקורות הטבה, קשה לזכור מה שייך למה. <a href=\"https://save.hania360.com/\">הנחה בכיס</a> נבנה כדי לרכז את זה: בוחרים חנות ורואים את האפשרויות הרלוונטיות.</p>"},{"slug":"spotting-real-sales","cat":"חיסכון","title":"איך לזהות מבצע אמיתי ולא רק תווית אדומה","desc":"מחיר \"לפני\" מנופח, מחיר ליחידה, מבצעי כמות ותמחור דינמי — כך בודקים אם ההנחה אמיתית.","read":6,"body":"<p>\"50% הנחה\" היא אחת הדרכים היעילות ביותר לגרום לאנשים לקנות. אבל אחוז ההנחה אומר מעט מאוד אם לא יודעים ממה הוא מחושב. כמה בדיקות פשוטות מבדילות בין מבצע אמיתי לבין שיווק.</p>\n<h2>1. ממה ההנחה מחושבת?</h2><p>ההנחה נמדדת מול מחיר \"לפני\". אם המחיר הזה הוא מחיר שהמוצר כמעט לא נמכר בו, ההנחה מנופחת. הבדיקה: חפשו את אותו מוצר, עם אותו דגם מדויק, בשתיים־שלוש חנויות נוספות ובאתרי השוואת מחירים. אם המחיר \"אחרי ההנחה\" דומה למחיר הרגיל במקומות אחרים — זה לא באמת מבצע.</p>\n<h2>2. מחיר ליחידה</h2><p>במזון, בחומרי ניקוי ובמוצרי טואלטיקה, האריזה משתנה כל הזמן. מבצע \"שלישי במתנה\" על אריזה קטנה יכול להיות יקר יותר ממחיר רגיל של אריזה גדולה. בישראל חלה חובה להציג מחיר ליחידת מידה (למשל ל־100 גרם) על רוב מוצרי הצריכה — וזה המספר שכדאי להשוות, לא המחיר על המדף.</p>\n<h2>3. מבצעי כמות</h2><p>\"2 ב־30\" משתלם רק אם הייתם קונים שניים בכל מקרה, ורק אם המוצר לא יתקלקל. במוצרים טריים, מבצע כמות הוא לעתים קרובות בזבוז. שאלה טובה לשאול: אם המבצע היה נגמר מחר, האם הייתי קונה את הכמות הזו?</p>\n<h2>4. דגם \"מיוחד למבצע\"</h2><p>בחשמל ובאלקטרוניקה, לפעמים נמכר במבצעים גדולים דגם עם שם דומה אבל מפרט שונה — פחות זיכרון, סוללה קטנה יותר, או דגם של שנה קודמת. השוו את מספר הדגם המלא, לא רק את השם.</p>\n<h2>5. תמחור דינמי</h2><p>באתרים רבים המחיר משתנה לפי זמן, ביקוש ולפעמים גם לפי היסטוריית הגלישה. אם אתם עוקבים אחרי מוצר, כדאי לרשום את המחיר בכמה תאריכים. כך תדעו מה המחיר הרגיל ומתי יש ירידה אמיתית. בטיסות ובמלונות, בדיקה מחלון גלישה פרטית נותנת נקודת השוואה נוספת.</p>\n<h2>6. עלויות נסתרות</h2><p>משלוח, דמי טיפול, אחריות מורחבת שמתווספת אוטומטית, או תשלום נוסף על אמצעי תשלום מסוים. המחיר הרלוונטי הוא הסכום בעמוד התשלום האחרון, לא בעמוד המוצר.</p>\n<h2>הבדיקה המהירה</h2><p>לפני קנייה במבצע: השוו מחיר במקום אחר, השוו מחיר ליחידה, ובדקו את הסכום הסופי בקופה. ואז — בדקו אם אפשר להוסיף על זה הטבה של מועדון או כרטיס. מבצע אמיתי פלוס הטבה אישית הוא בדרך כלל החיסכון הגדול ביותר. על השילוב הזה כתבנו ב<a href=\"/guides/compare-benefits-before-buying/\">מדריך להשוואת הטבות</a>.</p>"},{"slug":"choosing-credit-card-club","cat":"חיסכון","title":"איך לבחור כרטיס אשראי לפי ההטבות — ולא לפי הפרסומת","desc":"דמי כרטיס, הטבות שאתם באמת משתמשים בהן, נקודות ונוסעים מתמידים: מסגרת פשוטה לבחירת כרטיס שמשתלם לכם.","read":6,"body":"<p>פרסומות לכרטיסי אשראי מדגישות את ההטבה הכי מרשימה: הנחה גדולה ברשת מסוימת, נקודות לטיסות, או מתנת הצטרפות. אבל השאלה הנכונה היא אחרת: כמה הכרטיס הזה יחסוך <em>לכם</em>, לפי הקניות שאתם כבר עושים?</p>\n<h2>שלב 1: להבין לאן הכסף הולך</h2><p>קחו פירוט חיובים של שלושה חודשים ומיינו לקטגוריות: סופר, דלק, ביגוד, מסעדות, אונליין, חשבונות קבועים. בדרך כלל שתיים־שלוש קטגוריות הן רוב ההוצאה. הכרטיס המשתלם הוא זה שנותן הטבה טובה בדיוק בהן.</p>\n<h2>שלב 2: לחשב חיסכון שנתי צפוי</h2><p>לכל כרטיס שאתם שוקלים, חשבו: כמה אתם מוציאים בשנה ברשתות שבהן יש לו הטבה, כפול אחוז ההטבה. לדוגמה, 1,500 ₪ בחודש בסופר עם הטבה של 5% הם כ־900 ₪ בשנה. זה מספר שאפשר להשוות.</p>\n<h2>שלב 3: להוריד עלויות</h2><ul><li><strong>דמי כרטיס</strong> — חודשיים או שנתיים. לעתים יש פטור בהיקף שימוש מסוים, ולעתים אפשר לבקש פטור.</li><li><strong>תנאי מינימום</strong> — הטבות שדורשות היקף חיוב חודשי מינימלי.</li><li><strong>עמלות המרה</strong> — אם אתם קונים הרבה באתרים בחו\"ל, עמלת ההמרה יכולה לבטל את ההטבה.</li></ul>\n<h2>נקודות ומיילים: לחשב בזהירות</h2><p>כרטיסי נוסע מתמיד ונקודות נראים משתלמים, אבל ערך הנקודה תלוי במה שתמירו אותה אליו ובזמינות. כדי להשוות לכרטיס עם הנחה ישירה, צריך להעריך כמה שקלים שווה נקודה בשימוש שלכם בפועל — ולהביא בחשבון שנקודות יכולות לפוג. למי שלא טס הרבה, הנחה ישירה היא לרוב הבחירה הבטוחה יותר.</p>\n<h2>האם כדאי להחזיק כמה כרטיסים?</h2><p>לפעמים כן: כרטיס אחד לסופר, אחר לדלק. אבל כל כרטיס נוסף הוא עוד דמי כרטיס ועוד חיוב לעקוב אחריו. ההמלצה הכללית היא לא יותר משניים, ורק אם כל אחד מהם מחזיר את עלותו בבירור.</p>\n<h2>לבדוק שוב פעם בשנה</h2><p>הטבות כרטיסים משתנות, וגם ההרגלים שלכם. פעם בשנה, חזרו לחישוב. אם הכרטיס כבר לא משתלם — מעבר או ביטול הם בדרך כלל תהליך קצר.</p>\n<p>הערה: המדריך הזה מסביר איך לחשוב על הבחירה, ואינו ייעוץ פיננסי. התנאים המחייבים הם אלה שמפרסמת חברת הכרטיסים.</p>"},{"slug":"rtk-for-beginners","cat":"GPS ויונוספירה","title":"RTK למתחילים: איך מגיעים לדיוק של סנטימטרים","desc":"מה ההבדל בין מדידת קוד למדידת פאזה, מה זה Fix ו־Float, איך עובדים בסיס ורובר או NTRIP, ומה מגביל את הדיוק.","read":8,"body":"<p>מקלט GPS בטלפון נותן מיקום בדיוק של כמה מטרים. מערכות RTK (Real-Time Kinematic) מגיעות לסנטימטר עד שניים — ובזמן אמת. ההבדל לא נובע מלוויינים אחרים, אלא מאופן המדידה ומהשימוש בתחנה נוספת.</p>\n<h2>קוד מול פאזה</h2><p>מקלט רגיל מודד את המרחק ללוויין לפי <strong>הקוד</strong> שמשודר באות — רצף ביטים עם אורך \"תו\" של מאות מטרים. הדיוק של המדידה הזו מוגבל. מקלט RTK מודד גם את <strong>פאזת הגל הנושא</strong>. אורך הגל ב־L1 הוא כ־19 ס\"מ, ולכן אפשר למדוד את החלק השברי שלו בדיוק של מילימטרים.</p><p>הבעיה: המקלט יודע איפה הוא נמצא בתוך הגל, אבל לא כמה גלים שלמים יש בינו לבין הלוויין. המספר הלא ידוע הזה נקרא <strong>העמימות (ambiguity)</strong>, ופתרון שלו הוא לב ה־RTK.</p>\n<h2>בסיס ורובר</h2><p>תחנת בסיס עומדת בנקודה שהמיקום שלה ידוע, ומשדרת את המדידות שלה. המקלט הנייד (רובר) משווה את המדידות שלו לאלה של הבסיס. מאחר ששניהם רואים את אותם לוויינים דרך אטמוספרה דומה, רוב השגיאות — שעוני לוויין, מסלולים, ורוב ההשפעה של היונוספירה והטרופוספירה — מתבטלות בהפרש.</p><p>במקום בסיס פרטי, אפשר להתחבר לרשת תחנות קבועות דרך האינטרנט בפרוטוקול <strong>NTRIP</strong>. זה חוסך הקמת בסיס, אבל מחייב חיבור סלולרי יציב בשטח.</p>\n<h2>Fix, Float ומה הם אומרים</h2><ul><li><strong>Fix</strong> — העמימויות נפתרו למספרים שלמים. הדיוק ברמת סנטימטרים.</li><li><strong>Float</strong> — יש הערכה, אבל העמימויות עדיין לא נקבעו בוודאות. הדיוק יכול להיות מעשרות סנטימטרים ועד מטר.</li><li><strong>DGPS / Single</strong> — אין פתרון פאזה בכלל.</li></ul><p>חשוב לא להסתפק בכך שהמכשיר מציג Fix. במקרים נדירים מתקבל Fix שגוי. לכן מודדים מדי פעם נקודת ביקורת ידועה.</p>\n<h2>מה מגביל את הדיוק</h2><ol><li><strong>מרחק מהבסיס.</strong> ככל שהרובר רחוק יותר, האטמוספרה שמעליו שונה יותר מזו שמעל הבסיס, וההפרש כבר לא מבטל את השגיאות. עם בסיס בודד, מרחקים של עד כעשרה־עשרים ק\"מ נחשבים נוחים; מעבר לזה הזמן עד Fix מתארך והאמינות יורדת.</li><li><strong>יונוספירה פעילה.</strong> בזמן סערות גאומגנטיות גם מרחקים קצרים הופכים לבעייתיים. פירטנו ב<a href=\"/guides/kp-index-geomagnetic-storms/\">מדריך על מדד Kp</a>.</li><li><strong>שמיים חסומים ומולטיפאת.</strong> עצים, בניינים וקירות חוסמים לוויינים ויוצרים החזרים. ראו <a href=\"/guides/multipath-urban-gnss/\">המדריך על מולטיפאת</a>.</li><li><strong>עיכוב בתיקונים.</strong> חיבור סלולרי חלש גורם לתיקונים להגיע באיחור, והפתרון נופל ל־Float.</li></ol>\n<h2>טיפים לעבודה בשטח</h2><p>הקפידו על מסכת גובה (לא להשתמש בלוויינים נמוכים מאוד), על מוט מאונך, ועל זמן מדידה של כמה שניות לפחות אחרי Fix. בתחילת היום ובסופו מדדו נקודה ידועה. ולפני יציאה, בדקו את מצב היונוספירה — למשל ב<a href=\"https://gps.hania360.com/\">HaniaION</a>.</p>"},{"slug":"multi-constellation-gnss","cat":"GPS ויונוספירה","title":"GPS, Galileo, GLONASS ו־BeiDou: למה מקלט רב־מערכתי מדויק יותר","desc":"מה ההבדל בין מערכות הניווט הלוויינית, מה זה GNSS, ולמה יותר לוויינים משפרים את הגאומטריה ואת הזמינות.","read":6,"body":"<p>\"GPS\" הפך לשם כללי לניווט לווייני, אבל GPS הוא רק אחת ממערכות אחדות. השם הכללי הוא <strong>GNSS</strong> — Global Navigation Satellite System. רוב המקלטים המודרניים, כולל רוב הטלפונים, קולטים כמה מערכות במקביל.</p>\n<h2>המערכות הגלובליות</h2><div class=\"table-wrap\"><table><thead><tr><th>מערכת</th><th>מפעילה</th><th>הערות</th></tr></thead><tbody><tr><td>GPS</td><td>ארצות הברית</td><td>המערכת הוותיקה; אותות L1, L2 ו־L5 בלוויינים החדשים</td></tr><tr><td>GLONASS</td><td>רוסיה</td><td>מבנה אות שונה היסטורית, מה שמסבך מעט שילוב ב־RTK</td></tr><tr><td>Galileo</td><td>האיחוד האירופי</td><td>מערכת אזרחית; אותות E1 ו־E5 באיכות גבוהה</td></tr><tr><td>BeiDou</td><td>סין</td><td>כיסוי גלובלי מלא בשנים האחרונות, מספר גדול של לוויינים</td></tr></tbody></table></div><p>לצדן יש מערכות אזוריות, כמו QZSS היפנית ו־NavIC ההודית, שמשפרות את הכיסוי באזורים מסוימים.</p>\n<h2>למה יותר לוויינים זה טוב יותר</h2><p>כדי לחשב מיקום צריך לפחות ארבעה לוויינים. אבל הדיוק לא תלוי רק במספר — הוא תלוי ב<strong>גאומטריה</strong>: כמה טוב הלוויינים מפוזרים בשמיים. המדד לכך נקרא <strong>DOP</strong> (Dilution of Precision). לוויינים שמרוכזים בכיוון אחד נותנים DOP גבוה ודיוק ירוד; לוויינים מפוזרים לכל הכיוונים נותנים DOP נמוך.</p><p>כשמקלט קולט ארבע מערכות, יש לו בדרך כלל עשרות לוויינים בשמיים במקום כעשרה. גם אם חלק מהשמיים חסום, נשארים מספיק לוויינים בפיזור טוב.</p>\n<h2>איפה זה מורגש במיוחד</h2><ul><li><strong>בעיר</strong> — בין בניינים גבוהים רואים רק רצועה צרה של שמיים. יותר לוויינים זמינים מגדילים את הסיכוי שיהיו מספיק ברצועה הזו.</li><li><strong>ביער ובאזורים הרריים</strong> — מאותה סיבה.</li><li><strong>ב־RTK</strong> — יותר לוויינים מקצרים את הזמן עד Fix ומשפרים את האמינות שלו.</li></ul>\n<h2>ומה עם שני תדרים?</h2><p>זה שיפור נפרד וחשוב לא פחות. מקלט בשני תדרים יכול לחשב ולבטל את רוב השגיאה של היונוספירה, כמו שהסברנו ב<a href=\"/guides/ionosphere-and-gps-accuracy/\">מדריך על יונוספירה ו־GPS</a>. השילוב של כמה מערכות ושני תדרים הוא מה שהופך טלפונים חדשים למדויקים בהרבה מאלה של לפני עשור.</p>\n<h2>איך לבדוק מה המכשיר שלכם קולט</h2><p>יש אפליקציות שמציגות את הלוויינים הנקלטים, את המערכת של כל לוויין ואת עוצמת האות. זו דרך טובה להבין למה המיקום טוב במקום אחד וגרוע באחר.</p>"},{"slug":"multipath-urban-gnss","cat":"GPS ויונוספירה","title":"מולטיפאת: למה GPS משתגע ליד בניינים ואיך מצמצמים את זה","desc":"איך החזרים של אות מקירות, מתכת ומים יוצרים שגיאות מיקום, איך מזהים אותם, ומה עושים כדי לצמצם אותם במדידה.","read":6,"body":"<p>שגיאות של היונוספירה משפיעות על אזור שלם. מולטיפאת היא בעיה מקומית לחלוטין: שני מקלטים במרחק עשרה מטרים זה מזה יכולים לקבל תוצאות שונות מאוד, רק בגלל מה שנמצא סביבם.</p>\n<h2>מה זה מולטיפאת</h2><p>אות הלוויין מגיע לאנטנה בדרך ישירה, אבל גם מוחזר ממשטחים — קיר זכוכית, גג מתכת, רכב חונה, משטח מים. ההחזר עובר מסלול ארוך יותר, ולכן מגיע באיחור. כשהמקלט מקבל את האות הישיר ואת ההחזר יחד, המדידה מתעוותת. במקרה הגרוע, האות הישיר חסום לגמרי והמקלט מודד רק את ההחזר — ואז השגיאה יכולה להיות גדולה במיוחד.</p>\n<h2>איך מזהים שזו הבעיה</h2><ul><li>המיקום \"קופץ\" או נודד כשעומדים ליד בניין, ומתייצב כשמתרחקים ממנו.</li><li>עוצמת האות (SNR) של חלק מהלוויינים משתנה באופן לא סדיר.</li><li>ב־RTK, הפתרון נופל שוב ושוב ל־Float במקום מסוים, גם כשהיונוספירה שקטה.</li><li>הבעיה חוזרת באותו מקום, אבל בשעות שונות היא נראית אחרת — כי הלוויינים נמצאים בזוויות אחרות.</li></ul>\n<h2>איך מצמצמים</h2><ol><li><strong>מיקום האנטנה.</strong> להרחיק ממשטחים מחזירים ככל האפשר ולהגביה, כדי שיהיה קו ראייה פתוח לשמיים.</li><li><strong>מסכת גובה.</strong> להגדיר במקלט התעלמות מלוויינים נמוכים מאוד (לרוב 10°–15°). האותות שלהם הם אלה שהכי חשופים להחזרים מהסביבה.</li><li><strong>מסכת SNR.</strong> להתעלם מאותות חלשים במיוחד, שסביר שהם מוחזרים.</li><li><strong>אנטנה איכותית.</strong> אנטנות גאודטיות בנויות לדחות אותות שמגיעים מלמטה ומהצדדים. לתחנת בסיס זה חשוב במיוחד — מולטיפאת בבסיס \"מדביק\" שגיאה לכל המדידות.</li><li><strong>זמן.</strong> מולטיפאת משתנה עם תנועת הלוויינים. מדידה ארוכה יותר, או מדידה חוזרת בשעה אחרת, מאפשרת לזהות תוצאה חריגה.</li></ol>\n<h2>בסיס: המקום הכי חשוב לבחור נכון</h2><p>אם אתם מקימים תחנת בסיס קבועה, הקדישו זמן לבחירת המיקום: גג פתוח, בלי מעקות מתכת גבוהים ומזגנים סמוכים, רחוק מקירות גבוהים. בדקו את איכות הנתונים לאורך יממה לפני שמסתמכים עליה.</p><p>כשמשהו לא עובד בשטח, חשוב להבחין בין בעיה מקומית (מולטיפאת) לבעיה אזורית (יונוספירה). נתוני היונוספירה ב<a href=\"https://gps.hania360.com/\">HaniaION</a> עוזרים לשלול או לאשר את האפשרות השנייה.</p>"},{"slug":"polymer-concrete-casting-basics","cat":"יצירה","title":"יציקה בבטון פולימרי: מה חשוב לדעת לפני שמתחילים","desc":"תבניות, יחסי ערבוב, בועות, זמן ייבוש, ליטוש ואטימה — ומה חשוב לזכור לגבי בטיחות בעבודה עם חומרים על בסיס צמנט.","read":7,"body":"<p>בטון פולימרי — תערובת על בסיס צמנט או מינרלים עם תוסף פולימרי — הפך לחומר אהוב ביצירה. הוא מאפשר ליצוק כלים, מגשים, כלי לנרות, עציצים ואביזרי עיצוב עם מראה של אבן או בטון, אבל דק וקל יותר מבטון רגיל. יש בשוק כמה סוגי תערובות, ולכל אחת הוראות משלה. המדריך הזה עוסק בעקרונות המשותפים.</p>\n<h2>תבניות</h2><p><strong>תבניות סיליקון</strong> הן הנוחות ביותר: גמישות, קלות לשחרור, ומשחזרות פרטים עדינים. <strong>תבניות פלסטיק קשיח</strong> זולות, אבל קשה יותר לשחרר מהן, והן מתאימות לצורות פשוטות. לפני כל יציקה, ודאו שהתבנית נקייה ויבשה לגמרי. בתבניות שאינן סיליקון נדרש לרוב חומר שחרור.</p>\n<h2>ערבוב</h2><ul><li><strong>לשקול, לא להעריך.</strong> יחס האבקה לנוזל קובע את החוזק ואת הגימור. עבדו לפי ההוראות של היצרן, ושקלו במשקל דיגיטלי.</li><li><strong>להוסיף אבקה לנוזל</strong> (או לפי ההוראות), בהדרגה, ולערבב עד שאין גושים.</li><li><strong>לערבב מספיק אבל לא יותר מדי.</strong> ערבוב קצר משאיר גושים; ערבוב אגרסיבי מכניס אוויר.</li><li><strong>פיגמנטים</strong> מוסיפים בכמות קטנה ובאופן עקבי. אם רוצים שכמה פריטים ייראו זהים, שקלו גם את הפיגמנט.</li></ul>\n<h2>בועות — הבעיה הנפוצה</h2><p>בועות אוויר יוצרות חורים על פני השטח. כדי לצמצם אותן: מורחים שכבה ראשונה דקה על דפנות התבנית עם מכחול, ורק אז ממלאים; יוצקים לאט מגובה נמוך; ואחרי המילוי מקישים בעדינות על התבנית או מרעידים אותה כדקה, כדי שהבועות יעלו.</p>\n<h2>ייבוש ושחרור</h2><p>זמן השחרור מהתבנית משתנה לפי החומר, העובי והטמפרטורה — מכמה שעות ועד יממה. שחרור מוקדם מדי שובר פינות. גם אחרי השחרור החומר ממשיך להתקשות, ובדרך כלל כדאי לחכות כמה ימים לפני ליטוש, צביעה או שימוש.</p>\n<h2>ליטוש ואטימה</h2><p>ליטוש בנייר זכוכית רטוב, מגס לעדין, מחליק שוליים ומסיר עודפים. חומרים על בסיס צמנט סופגים נוזלים, ולכן פריט שיבוא במגע עם מים — עציץ, תחתית, כלי — צריך אטימה בחומר מתאים. פריטים שיבואו במגע עם מזון דורשים חומר אטימה שמאושר לכך במפורש.</p>\n<h2>בטיחות</h2><p>חומרים על בסיס צמנט הם בסיסיים (אלקליים) ועלולים לגרות את העור, ולכן עובדים עם כפפות. בזמן מזיגת אבקה ובזמן ליטוש יבש נוצר אבק — כדאי לעבוד במקום מאוורר ועם מסכת אבק, או לעדיף ליטוש רטוב. שמרו את החומרים הרחק מהישג ידם של ילדים, ואל תשפכו שאריות לכיור — הן מתקשות בצנרת.</p>\n<h2>רעיון לפרויקט ראשון</h2><p>כלי נר קטן הוא פרויקט ראשון מצוין: תבנית פשוטה, כמות חומר קטנה, ושימוש מיידי. אחרי שהכלי אטום, אפשר ליצוק לתוכו נר לפי <a href=\"/guides/beginners-guide-candle-making/\">המדריך ליציקת נרות</a>. בסדנאות של <a href=\"https://elinoya.hania360.com/\">אלינויה</a> עוברים את כל התהליך הזה בליווי.</p>"},{"slug":"choosing-candle-fragrance","cat":"יצירה","title":"איך בוחרים ריח לנר: שמנים, עומס ריח ושילובים","desc":"ההבדל בין שמן ריחני לשמן אתרי, מה זה ריח קר וריח חם, כמה ריח מוסיפים ואיך מרכיבים שילוב שעובד.","read":6,"body":"<p>ריח הוא החלק שהכי קל לטעות בו בנר. ריח שמרגיש חזק בבקבוק יכול להיעלם בנר, ושילוב שנשמע טוב על הנייר עלול לצאת עכור. כמה עקרונות בסיסיים חוסכים הרבה ניסיונות.</p>\n<h2>שמן ריחני או שמן אתרי?</h2><p><strong>שמני ריח ייעודיים לנרות</strong> מיוצרים כדי להחזיק מעמד בחום ולהתפזר טוב בשעווה. הם מגיעים במגוון עצום של ריחות, ורובם מלווים בגיליון נתונים של היצרן. <strong>שמנים אתריים</strong> הם תמציות צמחיות. חלקם מתנדפים מהר ולא מחזיקים טוב בנר, והם יקרים יותר. אפשר להשתמש בהם, אבל התוצאה לרוב עדינה יותר. בכל מקרה, השתמשו רק בשמנים שהיצרן מציין שהם מתאימים לנרות.</p>\n<h2>ריח קר וריח חם</h2><p><strong>ריח קר</strong> הוא מה שמריחים מנר כבוי. <strong>ריח חם</strong> הוא מה שמתפזר בחדר כשהנר דולק. הם לא תמיד זהים: יש ריחות שחזקים בקר וחלשים בחם, ולהפך. לכן הבדיקה האמיתית היא תמיד הדלקה — בחדר סגור בגודל רגיל, אחרי שהנר עבר ייצוב.</p>\n<h2>כמה ריח להוסיף</h2><p>\"עומס ריח\" הוא אחוז השמן ממשקל השעווה. לכל שעווה יש עומס מקסימלי שהיצרן מציין, ובדרך כלל עובדים בטווח של 6%–10%. יותר ריח מהמקסימום לא יחזק את הנר; הוא עלול לגרום לשמן לצוף על פני השטח, לפגוע בשריפה ולייצר עשן. אם הריח חלש, בדקו קודם את טמפרטורת ההוספה, את זמן הייצוב ואת גודל הפתיל — לפני שמוסיפים עוד שמן.</p>\n<h2>איך בונים שילוב</h2><p>בבשמים מדברים על שלוש שכבות: <strong>תווים עליונים</strong> (הדרים, עשבי תיבול — מורגשים ראשונים ונעלמים מהר), <strong>תווי לב</strong> (פרחים, תבלינים) ו<strong>תווי בסיס</strong> (עצים, וניל, ענבר — עמוקים ומחזיקים). שילוב מאוזן כולל בדרך כלל משהו מכל שכבה. כמה כללי אצבע:</p><ul><li>התחילו בשניים, לא בחמישה. שילוב של שני ריחות קל יותר לשלוט בו.</li><li>ערבבו כמויות קטנות ורשמו יחסים מדויקים, כדי שתוכלו לשחזר.</li><li>שילובים בטוחים למתחילים: הדר עם עשב (לימון ורוזמרין), פרח עם עץ (לבנדר וארז), תבלין עם מתוק (קינמון ווניל).</li><li>תנו לתערובת לנוח יום לפני שמוסיפים אותה לשעווה — הריח משתנה מעט.</li></ul>\n<h2>בטיחות</h2><p>שמני ריח מרוכזים עלולים לגרות את העור, ולכן עובדים עם כפפות ונמנעים ממגע. יצרנים אחראיים מפרסמים גיליון בטיחות ומסמך התאמה לתקני IFRA, שמגדירים כמויות מותרות לכל שימוש. אם אתם מוכרים נרות, גיליונות אלה חשובים גם לסימון הנכון של המוצר.</p>\n<p>להמשך: <a href=\"/guides/beginners-guide-candle-making/\">המדריך המלא ליציקת נרות למתחילים</a>. ובסדנאות של <a href=\"https://elinoya.hania360.com/\">אלינויה</a> אפשר להתנסות בהרכבת ריחות בליווי.</p>"}];
