const ABOUT = layout("אודות Hania360","מידע על Hania360 והפרויקטים הנחה בכיס, HaniaION ואלינויה.",`<article class="legal"><h1>אודות Hania360</h1><p>Hania360 הוא בית דיגיטלי לפרויקטים שימושיים בתחומי טכנולוגיה, חיסכון ויצירה. הרעיון המשותף הוא לקחת מידע או תהליך מפוזר ולהפוך אותו לחוויה פשוטה וברורה יותר.</p><h2>הפרויקטים</h2><p><strong>הנחה בכיס</strong> מסייע לרכז ולבדוק אפשרויות חיסכון לפני תשלום, לרבות הטבות, כרטיסים, שוברים וקאשבק. <strong>HaniaION</strong> מספק כלים הקשורים ל-GPS ולנתוני יונוספירה. <strong>אלינויה</strong> הוא אתר לסדנאות בוטיק ליצירה והשראה.</p><h2>איך אנחנו עובדים</h2><p>אנחנו שואפים להציג מידע ברור, שימושי ונגיש. מידע מסחרי והטבות עשויים להשתנות אצל הספקים עצמם, ולכן התנאים הסופיים של הגוף המציע הם הקובעים. כאשר נעשה שימוש בקישור שותף, אנו שואפים להציג גילוי נאות.</p></article>`,"/about");

const PRIVACY = layout("מדיניות פרטיות — Hania360","מדיניות הפרטיות של Hania360.",`<article class="legal"><h1>מדיניות פרטיות</h1><p>עודכן לאחרונה: 1 באוקטובר 2026.</p><p>Hania360 מכבד את פרטיות המשתמשים. דף הבית עשוי לאסוף מידע טכני בסיסי הנוצר בעת גלישה, כגון סוג מכשיר, דפדפן, עמודים שנצפו ונתוני שימוש מצרפיים, כאשר מופעלים שירותי מדידה או אבטחה.</p><h2>שירותים חיצוניים</h2><p>האתר עשוי להשתמש בשירותי תשתית, אבטחה, מדידה ופרסום של צדדים שלישיים. שירותים אלה עשויים להשתמש בעוגיות או בטכנולוגיות דומות בהתאם למדיניות שלהם ולהסכמות הנדרשות. פרויקטים שאליהם עוברים מתת-הדומיין עשויים להפעיל מדיניות פרטיות נוספת משלהם.</p><h2>פרסום וקישורי שותפים</h2><p>בעתיד עשוי להופיע באתר פרסום, לרבות באמצעות Google AdSense. שירותי פרסום עשויים להשתמש בעוגיות לצורך הצגת מודעות ומדידה, בכפוף לדין ולהגדרות ההסכמה הרלוונטיות. בחלק מהעמודים עשויים להופיע קישורי שותפים שיכולים להניב עמלה.</p><h2>יצירת קשר</h2><p>לשאלות בנושא פרטיות ניתן לפנות דרך עמוד <a href="/contact">יצירת הקשר</a>.</p></article>`,"/privacy");

const TERMS = layout("תנאי שימוש — Hania360","תנאי השימוש באתר Hania360.",`<article class="legal"><h1>תנאי שימוש</h1><p>השימוש ב-Hania360 ובקישורים ממנו נעשה לצורכי מידע ושימוש בשירותים המוצעים. אנו פועלים לשמור על מידע תקין ועדכני, אך אין התחייבות לכך שכל מידע, הטבה, מחיר, זמינות או תנאי מסחרי יישארו ללא שינוי.</p><h2>הטבות וחיסכון</h2><p>מידע על הטבות, כרטיסים, שוברים וקאשבק אינו מהווה התחייבות של בית העסק או הגוף המעניק את ההטבה. לפני ביצוע עסקה יש לבדוק את התנאים העדכניים אצל הספק הרלוונטי.</p><h2>קישורים חיצוניים</h2><p>Hania360 מקשר לשירותים ותתי-דומיינים נוספים. השימוש בהם עשוי להיות כפוף לתנאים ולמדיניות נוספים. קישורי שותפים עשויים להניב עמלה לבעל האתר ללא תוספת מחיר למשתמש.</p><h2>שינויים</h2><p>ניתן לעדכן את האתר, השירותים והתנאים מעת לעת כדי לשפר את המוצרים ולהתאים אותם לשינויים טכנולוגיים או משפטיים.</p></article>`,"/terms");

const CONTACT = layout("יצירת קשר — Hania360","דרכי יצירת קשר בנוגע ל-Hania360 ולפרויקטים.",`<article class="legal"><h1>יצירת קשר</h1><p>מצאתם מידע שדורש תיקון, קישור שלא עובד או שיש לכם שאלה לגבי אחד מפרויקטי Hania360? אפשר לפנות דרך ערוצי יצירת הקשר המופיעים בתוך השירות הרלוונטי.</p><h2>לאיזה שירות לפנות?</h2><p>בנושאי הטבות, שוברים וקאשבק היכנסו ל<a href="https://save.hania360.com/">הנחה בכיס</a>. בנושאי GPS ויונוספירה היכנסו ל<a href="https://gps.hania360.com/">HaniaION</a>. בנושאי סדנאות והרשמה היכנסו ל<a href="https://elinoya.hania360.com/">אלינויה</a>.</p><p>כך הפנייה מגיעה להקשר המתאים, יחד עם המידע העדכני של אותו שירות.</p></article>`,"/contact");

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const GUIDES=guidesPage();
    const pages = {"/":HOME,"/index.html":HOME,"/guides":GUIDES,"/guides/":GUIDES,...ARTICLE_PAGES,"/about":ABOUT,"/privacy":PRIVACY,"/terms":TERMS,"/contact":CONTACT};
    // ads.txt for Google AdSense. The Worker owns all apex-domain paths.
    if (url.pathname === "/ads.txt") return new Response("google.com, pub-5716914780099032, DIRECT, f08c47fec0942fa0\n",{headers:{"content-type":"text/plain; charset=utf-8","cache-control":"public, max-age=3600"}});
    // Canonicalize known routes with a trailing slash.
    if (url.pathname.length > 1 && url.pathname.endsWith("/") && pages[url.pathname.slice(0,-1)]) return Response.redirect(url.origin + url.pathname.slice(0,-1) + url.search, 301);
    if (url.pathname === "/robots.txt") return new Response("User-agent: *\nAllow: /\nSitemap: https://hania360.com/sitemap.xml\n",{headers:{"content-type":"text/plain; charset=utf-8"}});
    if (url.pathname === "/sitemap.xml") {
      const paths=["","guides",...ARTICLES.map(a=>"guides/"+a.slug),"about","privacy","terms","contact"];
      const xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+paths.map(p=>'<url><loc>https://hania360.com/'+p+'</loc><lastmod>2026-10-01</lastmod></url>').join("")+'</urlset>';
      return new Response(xml,{headers:{"content-type":"application/xml; charset=utf-8"}});
    }
    const page=pages[url.pathname];
    if (!page) return new Response(layout("העמוד לא נמצא | Hania360","העמוד המבוקש לא נמצא.",`<article class="legal"><h1>העמוד לא נמצא</h1><p>ייתכן שהקישור שגוי או שהעמוד הועבר.</p><p><a href="/">לדף הבית</a> · <a href="/guides">לכל המדריכים</a></p></article>`,url.pathname),{status:404,headers:{"content-type":"text/html; charset=utf-8"}});
    return new Response(page,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin"}});
  }
};
